repo_files.sstable.py:
"""Immutable Sorted String Table (SSTable) file representation."""

from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple


@dataclass
class SSTable:
    table_id: str
    level: int
    # Stored as sorted list of (key, value) pairs; value=None is a tombstone
    entries: List[Tuple[str, Optional[Any]]]

    def get(self, key: str) -> Tuple[bool, Optional[Any]]:
        for k, v in self.entries:
            if k == key:
                return True, v
        return False, None

repo_files.compactor.py:
"""LSM-tree multi-level SSTable compaction and merge sorter."""

from typing import Any, Dict, List, Optional, Tuple
from sstable import SSTable


class CompactionEngine:
    def __init__(self, max_level: int = 2):
        self.max_level = max_level

    def merge_sstables(self, target_level: int, tables: List[SSTable], new_table_id: str) -> SSTable:
        # Multi-way merge sort: later tables in list represent newer timestamps
        merged_map: Dict[str, Optional[Any]] = {}
        for table in tables:
            for k, v in table.entries:
                merged_map[k] = v

        # Sort by key
        sorted_pairs = sorted(merged_map.items(), key=lambda p: p[0])

        # BUG: Retains tombstones (value=None) even when target_level == self.max_level (bottom tier)!
        # At max_level, no older tables exist below, so tombstones should be purged!
        return SSTable(table_id=new_table_id, level=target_level, entries=sorted_pairs)

reference_fix.compactor.py:
"""LSM-tree multi-level SSTable compaction and merge sorter."""

from typing import Any, Dict, List, Optional, Tuple
from sstable import SSTable


class CompactionEngine:
    def __init__(self, max_level: int = 2):
        self.max_level = max_level

    def merge_sstables(self, target_level: int, tables: List[SSTable], new_table_id: str) -> SSTable:
        merged_map: Dict[str, Optional[Any]] = {}
        for table in tables:
            for k, v in table.entries:
                merged_map[k] = v

        sorted_pairs = sorted(merged_map.items(), key=lambda p: p[0])

        # Purge tombstones (value is None) when compacting into bottom level (max_level)
        if target_level >= self.max_level:
            sorted_pairs = [(k, v) for k, v in sorted_pairs if v is not None]

        return SSTable(table_id=new_table_id, level=target_level, entries=sorted_pairs)
